1	/**
2	 * @module productMatch
3	 *
4	 * Match ciente da **categoria/título de seção** entre itens extraídos de uma
5	 * requisição e o catálogo de produtos (produtos_master).
6	 *
7	 * Motivação: mensagens de requisição são hierárquicas — um cabeçalho de seção
8	 * ("Bolos no Pote") seguido de sub-itens só com o sabor ("chocolate"). Quando o
9	 * parser de IA dropa o prefixo da categoria, um match só-pelo-nome ancora em
10	 * qualquer produto com a palavra no nome (ex.: "chocolate" → "Mini de
11	 * Chocolate"). Estas funções comparam também "categoria + sabor", então
12	 * "chocolate" sob "Bolos no Pote" casa em "Bolo no Pote Chocolate".
13	 *
14	 * Puro: sem React, Supabase ou side-effects — testável isoladamente.
15	 */
16	
17	import { normalizeName, similarity } from '@/shared/lib/stringUtils';
18	
19	/** Item extraído (parcial) que será casado com o catálogo. */
20	export interface MatchableItem {
21	  name: string;
22	  /** Título/cabeçalho da seção a que o item pertence (ex.: "Bolos no Pote"). */
23	  category?: string;
24	}
25	
26	/** Produto de catálogo (forma mínima — qualquer objeto com `id` e `nome`). */
27	export interface MatchableProduct {
28	  id: number;
29	  nome: string;
30	}
31	
32	/** Threshold padrão de match fuzzy (alinhado à produção diária). */
33	export const DEFAULT_MATCH_THRESHOLD = 0.72;
34	
35	/** Acima disto, um match é forte o bastante pra travar mesmo sem coerência de título. */
36	export const HIGH_CONFIDENCE = 0.92;
37	
38	// Palavras de ligação ignoradas ao comparar o título da seção com o nome do produto.
39	const CATEGORY_STOPWORDS = new Set([
40	  'de', 'do', 'da', 'no', 'na', 'com', 'e', 'a', 'o', 'os', 'as', 'em', 'sem', 'ao', 'dos', 'das',
41	]);
42	
43	/** Reduz plural simples do português ("bolos" → "bolo", "minis" → "mini"). */
44	const stem = (t: string): string => (t.length > 4 && t.endsWith('s') ? t.slice(0, -1) : t);
45	
46	/**
47	 * Constrói os nomes-candidatos para o match fuzzy de um item.
48	 *
49	 * Sempre inclui o nome cru. Quando há um título de seção significativo e o nome
50	 * ainda não começa com ele, inclui também o nome qualificado pela categoria
51	 * (`"categoria sabor"`), para resgatar o produto completo.
52	 */
53	export function buildMatchCandidates(item: MatchableItem): string[] {
54	  const name = (item.name || '').trim();
55	  const cat = (item.category || '').trim();
56	  const candidates = [name];
57	  const catNorm = normalizeName(cat);
58	  if (catNorm && catNorm !== 'geral' && !normalizeName(name).startsWith(catNorm)) {
59	    candidates.push(`${cat} ${name}`.trim());
60	  }
61	  return candidates;
62	}
63	
64	/**
65	 * O produto casado é coerente com a categoria/título da seção do item?
66	 *
67	 * Verdadeiro quando o nome do produto contém a maioria dos tokens
68	 * significativos do título (tolerando plural). Itens sem categoria significativa
69	 * são sempre coerentes (não há título a violar).
70	 */
71	export function isCategoryConsistent(
72	  item: MatchableItem,
73	  product: Pick<MatchableProduct, 'nome'>,
74	): boolean {
75	  const cat = normalizeName((item.category || '').replace(/[/|]+/g, ' '));
76	  if (!cat || cat === 'geral') return true;
77	
78	  const prodNorm = normalizeName(product.nome);
79	  const tokens = cat
80	    .split(' ')
81	    .filter((t) => t.length >= 3 && !CATEGORY_STOPWORDS.has(t))
82	    .map(stem);
83	  if (tokens.length === 0) return true;
84	
85	  const hits = tokens.filter((t) => prodNorm.includes(t)).length;
86	  return hits >= Math.ceil(tokens.length / 2);
87	}
88	
89	/** Resultado do match ciente de categoria. Preserva o tipo do produto do catálogo. */
90	export interface CategoryAwareMatch<T extends MatchableProduct = MatchableProduct> {
91	  /** Melhor produto encontrado (ou `null` se o catálogo está vazio). */
92	  product: T | null;
93	  /** Score de similaridade [0..1] do melhor candidato. */
94	  score: number;
95	  /** O produto casado é coerente com o título da seção. */
96	  categoryConsistent: boolean;
97	  /** Qual candidato venceu: nome cru (`'bare'`) ou qualificado pela categoria (`'category'`). */
98	  via: 'bare' | 'category';
99	}
100	
101	/**
102	 * Acha o melhor produto do catálogo para um item, considerando o título da
103	 * seção. Quando a seção é significativa (categoria não-vazia e ≠ 'geral'),
104	 * prefere o MELHOR produto **coerente com ela** ao vencedor global de classe
105	 * errada — mesmo que o coerente tenha score mais baixo. Isso evita que um
106	 * sabor cru (ex.: "milho") ancore em um produto homônimo de outra classe
107	 * ("Milho" insumo) quando existe um produto correto na seção ("Mini
108	 * Caseirinho Milho").
109	 *
110	 * Rastreia dois melhores em paralelo:
111	 *  - `overall` — maior score global (comportamento anterior).
112	 *  - `consistent` — maior score apenas entre produtos coerentes com a seção.
113	 *
114	 * Retorna `consistent` quando a seção é significativa e há ao menos um
115	 * produto coerente; caso contrário, retorna `overall`.
116	 */
117	export function bestCatalogMatch<T extends MatchableProduct>(
118	  item: MatchableItem,
119	  catalog: T[],
120	): CategoryAwareMatch<T> {
121	  const candidates = buildMatchCandidates(item);
122	  const catNorm = normalizeName((item.category || '').trim());
123	  const sectionSignificant = !!catNorm && catNorm !== 'geral';
124	
125	  let overallBest: T | null = null;
126	  let overallScore = 0;
127	  let overallVia: 'bare' | 'category' = 'bare';
128	
129	  let consistentBest: T | null = null;
130	  let consistentScore = 0;
131	  let consistentVia: 'bare' | 'category' = 'bare';
132	
133	  candidates.forEach((cand, ci) => {
134	    const v: 'bare' | 'category' = ci === 0 ? 'bare' : 'category';
135	    for (const p of catalog) {
136	      const sim = similarity(cand, p.nome);
137	      if (sim > overallScore) {
138	        overallScore = sim;
139	        overallBest = p;
140	        overallVia = v;
141	      }
142	      if (sectionSignificant && isCategoryConsistent(item, p) && sim > consistentScore) {
143	        consistentScore = sim;
144	        consistentBest = p;
145	        consistentVia = v;
146	      }
147	    }
148	  });
149	
150	  // Quando a seção é significativa e há ao menos um produto coerente, preferir
151	  // o coerente — mesmo que o score seja menor que o global. O chamador decide
152	  // se o score é suficiente para travar via shouldAutoLock.
153	  if (sectionSignificant && consistentBest !== null) {
154	    return {
155	      product: consistentBest,
156	      score: consistentScore,
157	      categoryConsistent: true,
158	      via: consistentVia,
159	    };
160	  }
161	
162	  return {
163	    product: overallBest,
164	    score: overallScore,
165	    categoryConsistent: overallBest ? isCategoryConsistent(item, overallBest) : false,
166	    via: overallVia,
167	  };
168	}
169	
170	/**
171	 * Decide se um match deve travar automaticamente, ou ir pra revisão manual.
172	 *
173	 * Política "perguntar, não chutar":
174	 *  1. Abaixo do limiar → nunca trava.
175	 *  2. Coerente com o título da seção + acima do limiar → trava sempre.
176	 *  3. Incoerente: bypass de alta confiança SÓ via candidato qualificado pela
177	 *     categoria (`via === 'category'`), nunca via sabor cru (`via === 'bare'`).
178	 *     Isso impede que "milho" (score 1.0 em "Milho" insumo, via bare) trave
179	 *     mesmo sendo incoerente com a seção "Caseirinhos".
180	 */
181	export function shouldAutoLock(
182	  match: CategoryAwareMatch,
183	  threshold: number = DEFAULT_MATCH_THRESHOLD,
184	  highConfidence: number = HIGH_CONFIDENCE,
185	): boolean {
186	  if (!match.product || match.score < threshold) return false;
187	  if (match.categoryConsistent) return true;
188	  // Incoerente: bypass de alta confiança APENAS por candidato de categoria
189	  return match.via === 'category' && match.score >= highConfidence;
190	}
