1	import { describe, it, expect } from 'vitest';
2	import {
3	  buildMatchCandidates,
4	  isCategoryConsistent,
5	  bestCatalogMatch,
6	  shouldAutoLock,
7	  DEFAULT_MATCH_THRESHOLD,
8	} from '@/shared/lib/productMatch';
9	
10	// Catálogo realista da Momma (subset), incluindo o produto que causava o
11	// match errado da regressão ("Mini de Chocolate") e os produtos canônicos
12	// usados no caso real de "milho" sob "Caseirinhos".
13	const CATALOG = [
14	  { id: 1, nome: 'Bolo no Pote Chocolate' },
15	  { id: 2, nome: 'Bolo no Pote Banoffee' },
16	  { id: 3, nome: 'Bolo no Pote Ninho' },
17	  { id: 4, nome: 'Mini de Chocolate' },
18	  { id: 5, nome: 'Mini Ferrero Rocher' },
19	  { id: 6, nome: 'Gelato Chocolate' },
20	  { id: 7, nome: 'Tartelete Chocomelo' },
21	  { id: 8, nome: 'Bombom Morango' },
22	  // Produtos do caso real (A4): insumo homônimo e canônico correto
23	  { id: 9, nome: 'Milho' },
24	  { id: 10, nome: 'Mini Caseirinho Milho' },
25	  { id: 11, nome: 'Mini Brigadeiro' },
26	];
27	
28	describe('buildMatchCandidates', () => {
29	  it('inclui o nome qualificado pela categoria quando há título de seção', () => {
30	    expect(buildMatchCandidates({ name: 'chocolate', category: 'Bolos no Pote' })).toEqual([
31	      'chocolate',
32	      'Bolos no Pote chocolate',
33	    ]);
34	  });
35	
36	  it('não duplica quando o nome já começa com a categoria', () => {
37	    expect(
38	      buildMatchCandidates({ name: 'Bolo no Pote Chocolate', category: 'Bolo no Pote' }),
39	    ).toEqual(['Bolo no Pote Chocolate']);
40	  });
41	
42	  it('sem categoria significativa, devolve só o nome cru', () => {
43	    expect(buildMatchCandidates({ name: 'chocolate' })).toEqual(['chocolate']);
44	    expect(buildMatchCandidates({ name: 'chocolate', category: 'Geral' })).toEqual(['chocolate']);
45	  });
46	});
47	
48	describe('isCategoryConsistent', () => {
49	  it('produto coerente com o título da seção', () => {
50	    expect(
51	      isCategoryConsistent({ category: 'Bolos no Pote' }, { nome: 'Bolo no Pote Chocolate' }),
52	    ).toBe(true);
53	  });
54	
55	  it('produto incoerente com o título da seção', () => {
56	    expect(
57	      isCategoryConsistent({ category: 'Bolos no Pote' }, { nome: 'Mini de Chocolate' }),
58	    ).toBe(false);
59	  });
60	
61	  it('tolera plural no título (Minis → Mini ...)', () => {
62	    expect(isCategoryConsistent({ category: 'Minis' }, { nome: 'Mini Ferrero Rocher' })).toBe(true);
63	  });
64	
65	  it('item sem categoria é sempre coerente', () => {
66	    expect(isCategoryConsistent({}, { nome: 'Mini de Chocolate' })).toBe(true);
67	  });
68	});
69	
70	describe('bestCatalogMatch — regressão do título de seção', () => {
71	  it('"chocolate" sob "Bolos no Pote" casa em "Bolo no Pote Chocolate", NÃO em "Mini de Chocolate"', () => {
72	    const m = bestCatalogMatch({ name: 'chocolate', category: 'Bolos no Pote' }, CATALOG);
73	    expect(m.product?.nome).toBe('Bolo no Pote Chocolate');
74	    expect(m.via).toBe('category');
75	    expect(m.categoryConsistent).toBe(true);
76	    expect(m.score).toBeGreaterThan(0.9);
77	    expect(shouldAutoLock(m)).toBe(true);
78	  });
79	
80	  it('"banoffe" (typo) sob "Bolos no Pote" casa em "Bolo no Pote Banoffee"', () => {
81	    const m = bestCatalogMatch({ name: 'banoffe', category: 'Bolos no Pote' }, CATALOG);
82	    expect(m.product?.nome).toBe('Bolo no Pote Banoffee');
83	    expect(shouldAutoLock(m)).toBe(true);
84	  });
85	
86	  it('nome completo limpo continua casando em si mesmo (sem regressão)', () => {
87	    const m = bestCatalogMatch(
88	      { name: 'Bolo no Pote Ninho', category: 'Bolos no Pote' },
89	      CATALOG,
90	    );
91	    expect(m.product?.nome).toBe('Bolo no Pote Ninho');
92	    expect(m.score).toBeGreaterThan(0.9);
93	    expect(shouldAutoLock(m)).toBe(true);
94	  });
95	
96	  it('Mini correto sob "Minis" trava (plural tolerado)', () => {
97	    const m = bestCatalogMatch({ name: 'ferrero rocher', category: 'Minis' }, CATALOG);
98	    expect(m.product?.nome).toBe('Mini Ferrero Rocher');
99	    expect(shouldAutoLock(m)).toBe(true);
100	  });
101	});
102	
103	describe('shouldAutoLock — "perguntar, não chutar"', () => {
104	  it('match de score médio incoerente com o título vai pra revisão (não trava)', () => {
105	    // "ferrero rocher" digitado por engano sob "Bolos no Pote": com a nova preferência
106	    // por coerência, o produto devolvido passa a ser o melhor coerente da seção (um
107	    // "Bolo no Pote X") em vez de "Mini Ferrero Rocher". O score é baixo (abaixo do
108	    // limiar) porque "ferrero rocher" não combina bem com nenhum Bolo no Pote.
109	    // A asserção essencial — shouldAutoLock === false — é preservada.
110	    const m = bestCatalogMatch({ name: 'ferrero rocher', category: 'Bolos no Pote' }, CATALOG);
111	    expect(m.product?.nome).toMatch(/^Bolo no Pote/);
112	    expect(m.categoryConsistent).toBe(true);
113	    expect(shouldAutoLock(m)).toBe(false);
114	  });
115	
116	  it('abaixo do threshold nunca trava', () => {
117	    const m = bestCatalogMatch({ name: 'xpto inexistente' }, CATALOG);
118	    expect(shouldAutoLock(m)).toBe(false);
119	  });
120	
121	  it('catálogo vazio não trava nada', () => {
122	    const m = bestCatalogMatch({ name: 'chocolate', category: 'Bolos no Pote' }, []);
123	    expect(m.product).toBeNull();
124	    expect(shouldAutoLock(m)).toBe(false);
125	  });
126	});
127	
128	describe('bestCatalogMatch — regressão A4: milho/Caseirinhos (nunca trava Milho insumo)', () => {
129	  it('"milho" sob "Caseirinhos" sugere "Mini Caseirinho Milho", NUNCA "Milho" insumo', () => {
130	    // Caso real: "milho" cru sob seção "Caseirinhos" casava score 1.0 com o insumo
131	    // "Milho" (id 9) e travava errado. Com a preferência coerente, retorna o produto
132	    // correto da seção. O score é < 0.72 (string edit), então vai pra revisão (não
133	    // trava) — mas JÁ com "Mini Caseirinho Milho" pré-selecionado.
134	    const m = bestCatalogMatch({ name: 'milho', category: 'Caseirinhos' }, CATALOG);
135	    expect(m.product?.nome).toBe('Mini Caseirinho Milho');
136	    expect(m.product?.id).toBe(10);
137	    expect(m.categoryConsistent).toBe(true);
138	    expect(m.score).toBeLessThan(DEFAULT_MATCH_THRESHOLD);
139	    expect(shouldAutoLock(m)).toBe(false); // vai pra revisão com sugestão certa
140	  });
141	
142	  it('"Mini Caseirinho Milho" sob "Caseirinhos" — exato — trava (A1 parser herdado)', () => {
143	    // Quando o parser herda corretamente "Mini Caseirinho Milho" (via CATEGORY_PREFIX_MAP
144	    // + repairItemName da edge function), o score é 1.0 e shouldAutoLock trava.
145	    const m = bestCatalogMatch(
146	      { name: 'Mini Caseirinho Milho', category: 'Caseirinhos' },
