// STRICT VALIDATION: Filter against Active Master Catalog
// STRICT VALIDATION: Filter against Active Master Catalog
setProcessingStage('Validando catálogo...');
try {
  wideDebug('requisicao.ia_validacao_catalogo', 'Buscando catalogo ativo para validacao', { domain: 'requisicoes' });
  const { data: activeProducts, error: dbError } = await (supabase as any)
    .from('produtos_master')
    .select('id, nome, categoria_id, codigo_interno')
    .eq('ativo', true);

  if (dbError) throw dbError;

  if (activeProducts && activeProducts.length > 0) {
    const processedItems: AIProcessedItem[] = [];
    const lowConfidenceItems: AIProcessedItem[] = [];

    for (const item of allProcessedItems) {
      // Encontrar melhor match
      let bestMatch: typeof activeProducts[0] | null = null;
      let bestScore = 0;

      // 1. Tentar encontrar por Alias aprendido (match exato do termo original)
      // IMPORTANTE: Passamos o nome bruto, pois findProductByAlias faz a normalização internamente
      const learnedProductId = findProductByAlias(item.name);

      if (learnedProductId) {
        const learnedProduct = activeProducts.find(p => p.id === learnedProductId);
        if (learnedProduct) {
          wideDebug('requisicao.ia_match_aprendizado', 'Match por aprendizado', { domain: 'requisicoes', attributes: { itemName: item.name, produtoNome: learnedProduct.nome } });
          bestMatch = learnedProduct;
          bestScore = 1.0; // Confiança máxima
        }
      }

      // 2. Se não achou por alias, fuzzy ciente do TÍTULO DA SEÇÃO (categoria).
      // bestCatalogMatch prefere o produto coerente com a seção ao vencedor global
      // de classe errada. shouldAutoLock decide se trava (coerente + score ≥ 0.72)
      // ou manda pra revisão (incoerente / score baixo).
      if (!bestMatch) {
        const m = bestCatalogMatch({ name: item.name, category: item.category }, activeProducts);
        if (m.product && shouldAutoLock(m)) {
          bestScore = m.score;
          bestMatch = m.product;
          // falls through para o bloco de lock abaixo
        } else if (m.product) {
          // Sugestão coerente mas não travável → revisão com sugestão pré-selecionada
          const reviewItem = {
            ...item,
            name: m.product.nome,
            matchedId: m.product.id.toString(),
            code: (m.product as any).codigo_interno,
            matchConfidence: m.score,
            isLowConfidence: true,
            isLocked: false,
            originalName: item.name,
          };
          processedItems.push(reviewItem);
          lowConfidenceItems.push(reviewItem);
          continue;
        }
        // m.product === null → bestMatch permanece null → cai no else abaixo
      }

      const MATCH_THRESHOLD = 0.72; // Mesmo threshold da produção diária

      if (bestMatch && bestScore >= MATCH_THRESHOLD) {
        // Caminho alias (score 1.0) ou fuzzy coerente + shouldAutoLock true
        processedItems.push({
          ...item,
          name: bestMatch.nome,
          matchedId: bestMatch.id.toString(),
          matchConfidence: bestScore,
          originalName: item.name,
          code: (bestMatch as any).codigo_interno,
          isLocked: true
        });
      } else {
        // Sem produto no catálogo (m.product === null) ou alias abaixo do limiar
        const unidentifiedItem = {
          ...item,
          matchedId: undefined,
          matchConfidence: bestScore,
          isLowConfidence: true,
          originalName: item.name
        };
        processedItems.push(unidentifiedItem);
        lowConfidenceItems.push(unidentifiedItem);
      }
    }

    // STRICT UI: Only show fully matched items in the main list
    // Unmatched items reside in 'unmatchedItems' state and are shown in the modal
    const matchedItems = processedItems.filter(i => !i.isLowConfidence);
    setAllItems(matchedItems);
    // Agente revisor (assíncrono, não bloqueia a tela): segunda opinião sobre os matches.
    void runMatchReview(matchedItems, activeProducts);

    if (lowConfidenceItems.length > 0) {
      setUnmatchedItems(lowConfidenceItems);
      setIsMatchModalOpen(true);
      toast.warning(`${lowConfidenceItems.length} itens precisam de revisão manual.`);
    } else if (matchedItems.length > 0) {
      setUnmatchedItems([]);
      toast.success("Todos os itens foram mapeados com sucesso!", { duration: 4000 });
    } else {
      // 0 matcheados e 0 em revisão = nada reconhecido. Não fingir sucesso.
      setUnmatchedItems([]);
      toast.error("Nenhum item reconhecido na requisição. Revise o texto e tente novamente.");
    }
  }
} catch (validationErr) {
  handleError(validationErr, { domain: 'requisicoes', operation: 'validarProdutos', showToast: false });
  toast.error("Erro ao validar catálogo. Exibindo resultados brutos.");
  setAllItems(allProcessedItems); // Fallback
}

// (removido) o setAllItems(allProcessedItems) que existia aqui rodava fora do try e
// sobrescrevia o resultado do match estrito com itens crus (sem produto matcheado),
// contradizendo o "STRICT UI". O estado já vem de setAllItems(matchedItems) na
// validação, do fallback do catch, ou do SSE (result) quando não há catálogo.

// O toast de resultado já foi emitido na validação acima (sucesso / aviso de revisão /
// erro de "nada reconhecido"), com a contagem correta. NÃO emitir um success genérico
// aqui — antes ele disparava mesmo após erro de validação, mascarando o problema.
wideDebug('requisicao.ia_estado_atualizado', 'Estado atualizado', { domain: 'requisicoes' });

// Auto-redirect para aba de resultado após processamento
setTimeout(() => {
  wideDebug('requisicao.ia_navegando_resultado', 'Navegando para aba de resultado', { domain: 'requisicoes' });

